using System.Globalization;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;

namespace MoneyTweaks.Community.Server;

/// <summary>Where image files live. Keys are generated by the server only (never from user input).</summary>
public interface IObjectStore
{
    Task PutAsync(string key, byte[] data, string contentType, CancellationToken ct = default);
    Task<byte[]?> GetAsync(string key, CancellationToken ct = default);
    Task DeleteAsync(string key, CancellationToken ct = default);
}

public static partial class ObjectKeys
{
    [GeneratedRegex("^(img|thumb)/[0-9a-f]{32}(-[0-9a-f]{8})?\\.(png|jpg)$")] public static partial Regex Pattern();

    public static string Check(string key) =>
        Pattern().IsMatch(key) ? key : throw new ArgumentException("Invalid object key.", nameof(key));
}

/// <summary>
/// Files in a folder on a persistent disk (local development, or a single server with a mounted volume). Writes go to a
/// temporary file first and are then moved into place, so a crash never leaves a half-written image.
/// </summary>
public sealed class FileSystemObjectStore(string root) : IObjectStore
{
    private string PathOf(string key) => Path.Combine(root, ObjectKeys.Check(key).Replace('/', Path.DirectorySeparatorChar));

    public async Task PutAsync(string key, byte[] data, string contentType, CancellationToken ct = default)
    {
        var path = PathOf(key);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        var tmp = path + "." + Guid.NewGuid().ToString("N")[..8] + ".tmp";
        await File.WriteAllBytesAsync(tmp, data, ct);
        File.Move(tmp, path, overwrite: true);
    }

    public async Task<byte[]?> GetAsync(string key, CancellationToken ct = default)
    {
        var path = PathOf(key);
        return File.Exists(path) ? await File.ReadAllBytesAsync(path, ct) : null;
    }

    public Task DeleteAsync(string key, CancellationToken ct = default)
    {
        var path = PathOf(key);
        if (File.Exists(path)) File.Delete(path);
        return Task.CompletedTask;
    }
}

/// <summary>
/// S3-compatible object storage (Cloudflare R2, AWS S3, Backblaze B2, MinIO) over plain HTTPS with AWS Signature V4.
/// Objects are private: images are only served through the API, which checks moderation status and permissions.
/// </summary>
public sealed class S3ObjectStore(HttpClient http, S3Options o, TimeProvider clock) : IObjectStore
{
    public async Task PutAsync(string key, byte[] data, string contentType, CancellationToken ct = default)
    {
        using var req = Sign(HttpMethod.Put, key, data, contentType);
        using var resp = await http.SendAsync(req, ct);
        if (!resp.IsSuccessStatusCode) throw new IOException($"Object storage refused the upload ({(int)resp.StatusCode}).");
    }

    public async Task<byte[]?> GetAsync(string key, CancellationToken ct = default)
    {
        using var req = Sign(HttpMethod.Get, key, [], null);
        using var resp = await http.SendAsync(req, ct);
        if (resp.StatusCode == HttpStatusCode.NotFound) return null;
        if (!resp.IsSuccessStatusCode) throw new IOException($"Object storage read failed ({(int)resp.StatusCode}).");
        return await resp.Content.ReadAsByteArrayAsync(ct);
    }

    public async Task DeleteAsync(string key, CancellationToken ct = default)
    {
        using var req = Sign(HttpMethod.Delete, key, [], null);
        using var resp = await http.SendAsync(req, ct);
        if (!resp.IsSuccessStatusCode && resp.StatusCode != HttpStatusCode.NotFound) throw new IOException($"Object storage delete failed ({(int)resp.StatusCode}).");
    }

    private HttpRequestMessage Sign(HttpMethod method, string key, byte[] body, string? contentType)
    {
        ObjectKeys.Check(key);
        var endpoint = new Uri(o.Endpoint.TrimEnd('/'));
        var path = "/" + Uri.EscapeDataString(o.Bucket) + "/" + string.Join("/", key.Split('/').Select(Uri.EscapeDataString));
        var uri = new Uri(endpoint, path);
        var req = new HttpRequestMessage(method, uri);
        if (method == HttpMethod.Put)
        {
            req.Content = new ByteArrayContent(body);
            req.Content.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue(contentType ?? "application/octet-stream");
        }
        var now = clock.GetUtcNow().UtcDateTime;
        var payloadHash = Hex(SHA256.HashData(body));
        var headers = new SortedDictionary<string, string>(StringComparer.Ordinal)
        {
            ["host"] = uri.IsDefaultPort ? uri.Host : $"{uri.Host}:{uri.Port}",
            ["x-amz-content-sha256"] = payloadHash,
            ["x-amz-date"] = now.ToString("yyyyMMdd'T'HHmmss'Z'", CultureInfo.InvariantCulture),
        };
        if (method == HttpMethod.Put) headers["content-type"] = contentType ?? "application/octet-stream";
        var auth = SigV4.Authorization(method.Method, uri.AbsolutePath, "", headers, payloadHash, now, o.Region, "s3", o.AccessKeyId, o.SecretAccessKey);
        foreach (var (k, v) in headers)
        {
            if (k is "host" or "content-type") continue;
            req.Headers.TryAddWithoutValidation(k, v);
        }
        req.Headers.TryAddWithoutValidation("Authorization", auth);
        return req;
    }

    private static string Hex(byte[] b) => Convert.ToHexString(b).ToLowerInvariant();
}

/// <summary>AWS Signature Version 4 (header-based). Kept separate so it can be checked against AWS's published examples.</summary>
public static class SigV4
{
    public static string Authorization(string method, string canonicalPath, string canonicalQuery, IDictionary<string, string> headers,
        string payloadHash, DateTime utcNow, string region, string service, string accessKey, string secretKey)
    {
        var date = utcNow.ToString("yyyyMMdd", CultureInfo.InvariantCulture);
        var stamp = utcNow.ToString("yyyyMMdd'T'HHmmss'Z'", CultureInfo.InvariantCulture);
        var sorted = headers.OrderBy(h => h.Key.ToLowerInvariant(), StringComparer.Ordinal).ToList();
        var canonicalHeaders = string.Concat(sorted.Select(h => h.Key.ToLowerInvariant() + ":" + h.Value.Trim() + "\n"));
        var signedHeaders = string.Join(";", sorted.Select(h => h.Key.ToLowerInvariant()));
        var canonicalRequest = $"{method}\n{canonicalPath}\n{canonicalQuery}\n{canonicalHeaders}\n{signedHeaders}\n{payloadHash}";
        var scope = $"{date}/{region}/{service}/aws4_request";
        var toSign = $"AWS4-HMAC-SHA256\n{stamp}\n{scope}\n{Hex(SHA256.HashData(Encoding.UTF8.GetBytes(canonicalRequest)))}";
        var k = Hmac(Encoding.UTF8.GetBytes("AWS4" + secretKey), date);
        k = Hmac(k, region);
        k = Hmac(k, service);
        k = Hmac(k, "aws4_request");
        var signature = Hex(Hmac(k, toSign));
        return $"AWS4-HMAC-SHA256 Credential={accessKey}/{scope}, SignedHeaders={signedHeaders}, Signature={signature}";
    }

    private static byte[] Hmac(byte[] key, string data) => HMACSHA256.HashData(key, Encoding.UTF8.GetBytes(data));
    private static string Hex(byte[] b) => Convert.ToHexString(b).ToLowerInvariant();
}
